<?php
require __DIR__.'/../app/Models/Reservation.php';require __DIR__.'/../app/Models/GuardPharmacy.php';require __DIR__.'/../app/Models/Medicine.php';
function ok($v,$name){if(!$v)throw new RuntimeException($name);echo "OK $name\n";}
ok(GuardPharmacy::date(GuardPharmacy::parseDate('2026-11-24T12:00'),'Y-m-d\TH:i')==='2026-11-24T12:00','date locale');
try{GuardPharmacy::parseDate('2026-02-30T12:00');throw new RuntimeException('date invalide acceptée');}catch(DomainException $e){echo "OK date invalide refusée\n";}
if(!in_array('sqlite',PDO::getAvailableDrivers(),true)){fwrite(STDERR,"PDO SQLite absent : tests DB non exécutés.\n");exit(1);}
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$db->exec('PRAGMA foreign_keys=ON');$db->exec(file_get_contents(__DIR__.'/../database/migrations/sqlite.sql'));$db->exec("INSERT INTO client_users(nom,email,password) VALUES('A','a@example.test','x'),('B','b@example.test','x'); INSERT INTO medicament(nom,quantite) VALUES('Test',5)");
$stock=fn()=>(int)$db->query('SELECT quantite FROM medicament')->fetchColumn();
Reservation::create($db,1,1,3,'0197000000');ok($stock()===2,'blocage du stock');
try{Reservation::create($db,2,1,3,'0197000000');throw new RuntimeException('surreservation');}catch(DomainException $e){ok($stock()===2,'surreservation refusée');}
ok(!Reservation::transition($db,1,'cancelled',2),'isolation client');ok(!Medicine::setPhysicalStock($db,1,2,1),'inventaire inférieur aux réservations refusé');ok(Medicine::setPhysicalStock($db,1,6,1)&&$stock()===3,'stock physique ajusté');ok(Reservation::transition($db,1,'confirmed'),'confirmation');ok(Reservation::transition($db,1,'collected')&&$stock()===3,'retrait sans double déduction');ok(!Reservation::transition($db,1,'cancelled',1),'retrait définitif');
Reservation::create($db,1,1,2,'0197000000');ok(Reservation::transition($db,2,'rejected')&&$stock()===3,'refus libère');ok(!Reservation::transition($db,2,'rejected'),'refus non rejouable');Reservation::create($db,1,1,1,'0197000000');$db->exec('UPDATE reservations SET expires_at=0 WHERE id=3');ok(Reservation::expire($db)===1&&$stock()===3,'expiration libère');ok(Reservation::expire($db)===0,'expiration idempotente');
Reservation::create($db,1,1,1,'0197000000');ok(Reservation::transition($db,4,'cancelled',1)&&$stock()===3,'annulation client');
$input=['name'=>'Test','address'=>'Rue','commune'=>'Cotonou','phone'=>'0197000000'];GuardPharmacy::savePharmacy($db,$input,null);$id=(int)$db->lastInsertId();GuardPharmacy::schedule($db,$id,GuardPharmacy::date(time()-3600,'Y-m-d\TH:i'),GuardPharmacy::date(time()+3600,'Y-m-d\TH:i'));ok(count(GuardPharmacy::current($db))===1,'garde publiée');try{GuardPharmacy::schedule($db,$id,GuardPharmacy::date(time()-3600,'Y-m-d\TH:i'),GuardPharmacy::date(time()+3600,'Y-m-d\TH:i'));throw new RuntimeException('chevauchement accepté');}catch(DomainException $e){echo "OK chevauchement refusé\n";}$db->exec('UPDATE pharmacy_guards SET cancelled=1');ok(count(GuardPharmacy::current($db))===0,'garde annulée');GuardPharmacy::schedule($db,$id,GuardPharmacy::date(time()+7200,'Y-m-d\TH:i'),GuardPharmacy::date(time()+10800,'Y-m-d\TH:i'));ok((int)$db->query('SELECT COUNT(*) FROM pharmacy_guards')->fetchColumn()===2,'historique conservé');
$db->exec("INSERT INTO guard_pharmacies(name,address,commune,phone,start_at,end_at,active,is_olg) VALUES('Ancienne','Rue','Cotonou','0197000000',100,200,1,0)");GuardPharmacy::migrate($db);GuardPharmacy::migrate($db);ok((int)$db->query('SELECT COUNT(*) FROM pharmacy_guards WHERE legacy_id IS NOT NULL')->fetchColumn()===1,'migration idempotente');
$db->exec('UPDATE medicament SET prix=500,is_actif=0 WHERE id=1');$before=$stock();ok(Medicine::addStock($db,1,4)&&$stock()===$before+4,'entrée de stock');$m=$db->query('SELECT prix,is_actif FROM medicament WHERE id=1')->fetch();ok((float)$m['prix']===500.0&&(int)$m['is_actif']===0,'entrée sans changement de prix ni statut');
